#!/usr/bin/env python3
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-02
"""
spellcheck-candidates.py

Deterministic Hebrew spell-check CANDIDATE GENERATOR for the proofread
pipeline (Phase 0 spike + Phase 1 plan). Wraps `hspell` -- it never adjudicates: it only
emits {line, token, context} candidates that a downstream finder/LLM stage
adjudicates. When `hspell` is not on PATH, prints {"skipped": "no checker"}
and exits 0 -- the pipeline shape does not change, the stage is just a stub.

Three measured constraints from the plan's Phase 0 spike, implemented here
rather than re-derived:

  (a) hspell 1.4 reads ISO-8859-8 ONLY. Feeding it UTF-8 silently returns
      zero flags with exit 0 -- no error. A naive `iconv -f UTF-8 -t
      ISO-8859-8` ABORTS at the first niqqud (U+0591-U+05C7) or
      geresh/gershayim (U+05F3/U+05F4), after which hspell scores a
      truncated document without complaint (this measured 2, then 4, then
      10 flags off the same 60-flag vocabulary before the fix). This script
      transcodes lossily in BOTH directions (`errors="ignore"`, never a
      hard iconv round-trip) and ASSERTS that the number of Hebrew tokens
      it fed hspell equals the number of ispell-protocol entries hspell
      accounted for -- failing loudly (RuntimeError) on any shortfall
      rather than silently reporting a clean document.

  (b) Geresh (׳ U+05F3) and gershayim (״ U+05F4) are mapped to ASCII `'`/`"`
      *before* niqqud-stripping and transcoding, so Hebrew abbreviations
      (הרמב״ם, צה״ל) survive as one token instead of shredding into
      phantom flags at every stripped geresh -- this cost 10 of 60
      measured flags before the fix.

  (c) Tokens matched by the allowlist
      (src/skills/proofread/references/hspell-allowlist.txt, seeded with
      the measured ktiv-male false-positive class) are dropped before
      candidates are emitted, unioned with an optional per-project
      extension file at .academic-helper/hspell-allowlist.txt.

hspell's `-a` mode speaks the ispell pipe protocol: after a one-line banner,
each *source* line of input produces exactly one output entry per
whitespace-delimited token fed on that line (`*`/`+`/`-` = accepted,
`&`/`#` = flagged with/without suggestions), followed by one blank line
marking the end of that source line's group -- including source lines with
zero tokens. This script exploits that 1:1 structure to do the
fed-vs-accounted assertion per source line, not just document-wide.

Usage:
    python3 spellcheck-candidates.py --input article.md
        [--allowlist path] [--project-allowlist path] [--hspell-bin path]

--input               Path to the PROOF_BASE text/markdown file.
--allowlist           Path to the shipped allowlist (default:
                       src/skills/proofread/references/hspell-allowlist.txt).
--project-allowlist   Path to a per-project extension allowlist (default:
                       .academic-helper/hspell-allowlist.txt relative to the
                       current working directory; silently skipped if
                       absent).
--hspell-bin          Override the hspell executable name/path looked up on
                       PATH (mainly for tests).

Prints JSON to stdout and exits 0: either {"candidates": [...]} or
{"skipped": "no checker"} when hspell is not found. Exits 2 on a
missing/unreadable --input file. Raises (non-zero exit via traceback) if the
fed/accounted token-count invariant is violated -- that is a correctness
bug, not a recoverable condition, and must not be swallowed.

No third-party dependencies -- Python 3 standard library only.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import shutil
import subprocess
import sys
from typing import List, Optional, Set

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
DEFAULT_ALLOWLIST_PATH = os.path.join(
    REPO_ROOT, "src", "skills", "proofread", "references", "hspell-allowlist.txt"
)
DEFAULT_PROJECT_ALLOWLIST_PATH = os.path.join(
    os.getcwd(), ".academic-helper", "hspell-allowlist.txt"
)

# Teamim + niqqud (cantillation and points), Hebrew combining marks.
NIQQUD_RE = re.compile(r"[֑-ׇֽֿׁׂׅׄ]")
# Hebrew letters (+ ASCII quotes, once geresh/gershayim are mapped) form a token.
# A token is >=2 Hebrew letters, optionally with an internal geresh/gershayim
# (already mapped to ASCII) as in ר״מ. Single letters are never candidates —
# `א` as a standalone token is noise, not a misspelling.
HEBREW_TOKEN_RE = re.compile(r"[א-ת](?:['\"]?[א-ת])+")
# A word followed by a geresh/gershayim is an ABBREVIATION (פרופ׳, ר׳, התנ״ך).
# hspell has no entry for the truncated stem, so every one of them reports as a
# misspelling: this is the abbreviation-artifact class that cost 10 of the 60
# flags in the Phase 0 measurement. Detected by lookahead so the token is
# excluded rather than post-filtered by a guessed list of known abbreviations.
ABBREV_TOKEN_RE = re.compile(r"([א-ת](?:['\"]?[א-ת])*)(?=['\"])")

# ispell -a protocol line prefixes that mean "hspell flagged this token".
FLAG_PREFIXES = ("&", "#")
# Prefixes hspell uses for an accounted-but-accepted token.
ACCEPT_PREFIXES = ("*", "+", "-")


def load_allowlist(*paths: str) -> Set[str]:
    tokens: Set[str] = set()
    for path in paths:
        if not path or not os.path.isfile(path):
            continue
        with open(path, encoding="utf-8") as fh:
            for raw_line in fh:
                line = raw_line.strip()
                if not line or line.startswith("#"):
                    continue
                tokens.add(line)
    return tokens


def _normalize_for_hspell(line: str) -> str:
    """Map geresh/gershayim to ASCII, then strip niqqud -- in that order,
    so abbreviations are not shredded before their punctuation survives."""
    mapped = line.replace("׳", "'").replace("״", '"')
    return NIQQUD_RE.sub("", mapped)


def _tokenize(normalized_line: str) -> List[str]:
    """Candidate tokens for one already-normalized line.

    Abbreviation stems are dropped: a word immediately followed by a geresh or
    gershayim is an abbreviation, and hspell flags the stem every time. Keeping
    them would refill the candidate list with the exact noise class the Phase 0
    measurement identified (פרופ׳ -> פרופ, התנ״ך -> התנ, הרמב״ם -> הרמב).
    """
    abbrevs = set(ABBREV_TOKEN_RE.findall(normalized_line))
    return [tok for tok in HEBREW_TOKEN_RE.findall(normalized_line) if tok not in abbrevs]


def _run_hspell(hspell_bin: str, feed_text: str) -> str:
    payload = feed_text.encode("iso-8859-8", errors="ignore")
    proc = subprocess.run(
        [hspell_bin, "-a"],
        input=payload,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=60,
    )
    if proc.returncode != 0:
        raise RuntimeError(
            f"hspell exited {proc.returncode}: {proc.stderr.decode('iso-8859-8', errors='ignore')}"
        )
    return proc.stdout.decode("iso-8859-8", errors="ignore")


def _parse_hspell_groups(output: str, expected_groups: int) -> List[List[str]]:
    """Split ispell-protocol output into one entry-list per source line.

    The first non-blank output line is the version banner and is discarded.
    Every subsequent group of non-blank lines, terminated by a blank line,
    corresponds to exactly one fed source line (including source lines with
    zero tokens, which still terminate with a lone blank line).
    """
    out_lines = output.split("\n")
    # Drop the banner: the first line, if present.
    if out_lines and out_lines[0].startswith("@(#)"):
        out_lines = out_lines[1:]
    elif out_lines and out_lines[0].strip() == "":
        out_lines = out_lines[1:]

    groups: List[List[str]] = []
    current: List[str] = []
    for line in out_lines:
        if line == "":
            groups.append(current)
            current = []
        else:
            current.append(line)
    # A non-empty trailing partial group with no terminating blank line
    # (can happen if stdout doesn't end on a blank line) is still a group.
    if current:
        groups.append(current)

    if len(groups) < expected_groups:
        raise RuntimeError(
            "spellcheck-candidates.py: hspell accounted for fewer source-line "
            f"groups ({len(groups)}) than were fed ({expected_groups}) -- "
            "the document was likely truncated by encoding loss."
        )
    return groups[:expected_groups]


def generate_candidates(
    text: str,
    hspell_bin: str,
    allowlist: Set[str],
) -> List[dict]:
    source_lines = text.splitlines()
    normalized_lines = [_normalize_for_hspell(line) for line in source_lines]
    token_lists = [_tokenize(nl) for nl in normalized_lines]
    feed_text = "\n".join(" ".join(tokens) for tokens in token_lists)

    fed_total = sum(len(tokens) for tokens in token_lists)

    if fed_total == 0:
        return []

    raw_output = _run_hspell(hspell_bin, feed_text)
    groups = _parse_hspell_groups(raw_output, expected_groups=len(source_lines))

    accounted_total = sum(len(group) for group in groups)
    if accounted_total != fed_total:
        raise RuntimeError(
            "spellcheck-candidates.py: token-count mismatch -- fed "
            f"{fed_total} Hebrew tokens to hspell but it accounted for "
            f"{accounted_total}. Refusing to report a possibly-truncated "
            "scan; this is the ISO-8859-8 truncation failure mode from "
            "Phase 0 of the proofread plan."
        )

    candidates: List[dict] = []
    for line_index, (tokens, group) in enumerate(zip(token_lists, groups)):
        if len(tokens) != len(group):
            raise RuntimeError(
                "spellcheck-candidates.py: token-count mismatch on source "
                f"line {line_index + 1} -- fed {len(tokens)} tokens, "
                f"hspell accounted for {len(group)}."
            )
        for token, entry in zip(tokens, group):
            if not entry.startswith(FLAG_PREFIXES):
                continue
            if token in allowlist:
                continue
            candidates.append(
                {
                    "line": line_index + 1,
                    "token": token,
                    "context": source_lines[line_index],
                }
            )

    return candidates


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Generate Hebrew spell-check candidates via hspell (candidate generator only).",
    )
    parser.add_argument("--input", required=True, help="Path to the PROOF_BASE text/markdown file.")
    parser.add_argument("--allowlist", default=DEFAULT_ALLOWLIST_PATH, help="Shipped allowlist path.")
    parser.add_argument(
        "--project-allowlist",
        default=DEFAULT_PROJECT_ALLOWLIST_PATH,
        help="Per-project extension allowlist (silently skipped if absent).",
    )
    parser.add_argument(
        "--hspell-bin",
        default="hspell",
        help="hspell executable name or path (looked up on PATH if bare).",
    )
    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_arg_parser()
    args = parser.parse_args(argv)

    try:
        with open(args.input, encoding="utf-8") as fh:
            text = fh.read()
    except OSError as exc:
        print(f"spellcheck-candidates.py: cannot read --input: {exc}", file=sys.stderr)
        return 2

    resolved_bin = shutil.which(args.hspell_bin)
    if resolved_bin is None:
        print(json.dumps({"skipped": "no checker"}))
        return 0

    allowlist = load_allowlist(args.allowlist, args.project_allowlist)
    candidates = generate_candidates(text, resolved_bin, allowlist)
    print(json.dumps({"candidates": candidates}, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())
